import attr


class SyncInputSource(object):
    pass


@attr.s(cmp=False)
class SyncHub(SyncInputSource):
    """
    Object representing synchronization source Sync Hub Master
    :param int total_delay_from_shm: Total delay in ns from Sync Hub Master, based on sync cable type and length.
    """
    total_delay_from_shm = attr.ib(type=int, default=10)


@attr.s(cmp=False)
class ToPServer(SyncInputSource):
    """
    Object representing Timing-over-Packet server
    :param str splan_ip_address: Synchronization plane  IP address
    """
    splane_ip_address = attr.ib(type=str)
